INSERT OR REPLACE INTO products (id, name, category, basePrice, price, wholesalePrice, stock, weightKg, image, description, active, createdAt, wholesale_available, wholesale_price, image_url, reseller_price, rating, featured, brand, is_bestseller, is_new, store_type)
VALUES ('dangote-cement-3x', 'Dangote Cement 3X — 50kg Bag, Grade 42.5R, Lagos (New)', 'cement-concrete', 7500, 7500, 6000, 10, 50.0, '/assets/products/dangote-cement-3x.webp', 'Dangote Cement 3X is the workhorse of Nigerian construction, trusted by contractors and homeowners for its consistent strength and reliable setting time. The 42.5R grade delivers rapid early strength development, making it ideal for structural concrete, block molding, and plastering works across residential and commercial projects. Manufactured to Nigerian Industrial Standards (NIS) and certified for quality, each 50kg bag provides predictable performance in mixing ratios. The low alkali content reduces the risk of aggregate reaction, and the fine particle distribution ensures smooth workability in mortar and plaster applications. For builders who demand the gold standard in Nigerian cement and refuse to compromise on structural integrity. Condition: Brand new, sealed Dangote factory bag, batch-coded for traceability.', 1, 1718400000, 1, 6000, '/assets/products/dangote-cement-3x.webp', 6000, 4.5, 0, 'Dangote', 0, 1, 'buildmart');

INSERT OR REPLACE INTO products (id, name, category, basePrice, price, wholesalePrice, stock, weightKg, image, description, active, createdAt, wholesale_available, wholesale_price, image_url, reseller_price, rating, featured, brand, is_bestseller, is_new, store_type)
VALUES ('dangote-cement-3x-1', 'Dangote Cement 3X — 50kg Bag, Grade 42.5R, Abuja (New)', 'cement-concrete', 7800, 7800, 6000, 10, 50.0, '/assets/products/dangote-cement-3x-1.webp', 'The Abuja-zone Dangote Cement 3X delivers the same trusted 42.5R rapid-hardening performance with logistics-optimized pricing for the Federal Capital Territory and northern regions. Each bag meets NIS 444-1:2003 standards with compressive strength testing at 2, 7, and 28 days. The consistent fineness modulus ensures uniform mixing with aggregates, and the controlled sulfate content makes it suitable for foundation works in varying soil conditions. The moisture-resistant packaging prevents premature hydration during storage, maintaining shelf stability for up to three months in dry conditions. For northern contractors and developers who need reliable cement supply with regional pricing advantages. Condition: Brand new, sealed Dangote factory bag, batch-coded.', 1, 1718400000, 1, 6000, '/assets/products/dangote-cement-3x-1.webp', 7000, 4.5, 0, 'Dangote', 0, 1, 'buildmart');

INSERT OR REPLACE INTO products (id, name, category, basePrice, price, wholesalePrice, stock, weightKg, image, description, active, createdAt, wholesale_available, wholesale_price, image_url, reseller_price, rating, featured, brand, is_bestseller, is_new, store_type)
VALUES ('lafarge-elephant-cement', 'Lafarge Elephant Cement — 50kg Bag, Grade 42.5R (New)', 'cement-concrete', 7600, 7600, 6000, 10, 50.0, '/assets/products/lafarge-elephant-cement.webp', 'Lafarge Elephant Cement is the premium alternative that has built some of Nigeria''s most iconic structures. The 42.5R Portland limestone cement offers excellent workability and reduced water demand, resulting in denser concrete with lower permeability. The optimized clinker composition delivers consistent 28-day compressive strength exceeding 42.5 MPa, and the low heat of hydration minimizes thermal cracking in mass concrete pours. The bag features tamper-evident sealing and QR-code traceability for authenticity verification. For discerning builders who want European-engineered cement technology with local manufacturing expertise. Condition: Brand new, sealed Lafarge factory bag, QR-coded for authenticity.', 1, 1718400000, 1, 6000, '/assets/products/lafarge-elephant-cement.webp', 6000, 4.5, 0, 'Lafarge', 0, 1, 'buildmart');

INSERT OR REPLACE INTO products (id, name, category, basePrice, price, wholesalePrice, stock, weightKg, image, description, active, createdAt, wholesale_available, wholesale_price, image_url, reseller_price, rating, featured, brand, is_bestseller, is_new, store_type)
VALUES ('bua-cement', 'BUA Cement — 50kg Bag, Grade 42.5R, Sokoto (New)', 'cement-concrete', 7400, 7400, 6000, 10, 50.0, '/assets/products/bua-cement.webp', 'BUA Cement from the Sokoto plant brings competitive pricing without sacrificing quality. The 42.5R grade meets all NIS requirements with consistent performance in block production, concrete casting, and floor screeding. The high early strength enables faster formwork stripping and accelerated construction schedules, reducing project timelines. The low chloride content makes it suitable for reinforced concrete in coastal and humid environments, and the fine grind ensures excellent adhesion in plaster and rendering works. For cost-conscious developers who want reliable cement with competitive northern pricing and proven performance. Condition: Brand new, sealed BUA factory bag, batch-coded.', 1, 1718400000, 1, 6000, '/assets/products/bua-cement.webp', 6000, 4.5, 0, 'BUA', 0, 1, 'buildmart');

INSERT OR REPLACE INTO products (id, name, category, basePrice, price, wholesalePrice, stock, weightKg, image, description, active, createdAt, wholesale_available, wholesale_price, image_url, reseller_price, rating, featured, brand, is_bestseller, is_new, store_type)
VALUES ('ibeto-cement', 'Ibeto Cement — 50kg Bag, Grade 42.5R (New)', 'cement-concrete', 7300, 7300, 5000, 10, 50.0, '/assets/products/ibeto-cement.webp', 'Ibeto Cement delivers consistent 42.5R performance at one of the most competitive price points in the market. The carefully controlled manufacturing process ensures uniform particle size distribution for predictable mixing behavior, and the optimal gypsum content regulates setting time for hot-weather concreting. The bag features moisture-barrier lining to prevent caking during humid storage, and the batch coding enables quality tracking. Suitable for general construction, block molding, and plastering in residential and light commercial applications. For budget-focused builders who want certified cement that meets structural requirements without premium pricing. Condition: Brand new, sealed Ibeto factory bag, batch-coded.', 1, 1718400000, 1, 5000, '/assets/products/ibeto-cement.webp', 6000, 4.5, 0, 'Ibeto', 0, 1, 'buildmart');

INSERT OR REPLACE INTO products (id, name, category, basePrice, price, wholesalePrice, stock, weightKg, image, description, active, createdAt, wholesale_available, wholesale_price, image_url, reseller_price, rating, featured, brand, is_bestseller, is_new, store_type)
VALUES ('unicem-cement', 'Unicem Cement — 50kg Bag, Grade 42.5R, Calabar (New)', 'cement-concrete', 7500, 7500, 6000, 10, 50.0, '/assets/products/unicem-cement.webp', 'Unicem Cement from the Calabar plant serves the South-South and southeastern markets with locally manufactured quality. The 42.5R grade provides the rapid strength gain needed for tropical construction schedules, and the controlled C3A content improves sulfate resistance in foundation works. The consistent quality control from raw material quarrying to finished product ensures batch-to-batch uniformity, critical for large-scale projects. The packaging includes moisture-resistant inner lining for humid coastal storage conditions. For South-South contractors who prefer regional supply chains with reduced logistics costs and reliable quality. Condition: Brand new, sealed Unicem factory bag, batch-coded.', 1, 1718400000, 1, 6000, '/assets/products/unicem-cement.webp', 6000, 4.5, 0, 'Unicem', 0, 1, 'buildmart');

INSERT OR REPLACE INTO products (id, name, category, basePrice, price, wholesalePrice, stock, weightKg, image, description, active, createdAt, wholesale_available, wholesale_price, image_url, reseller_price, rating, featured, brand, is_bestseller, is_new, store_type)
VALUES ('dangote-blocmaster', 'Dangote BlocMaster — 50kg Bag, Block Molding Specialist (New)', 'building-materials', 7200, 7200, 5000, 10, 25.0, '/assets/products/dangote-blocmaster.webp', 'Dangote BlocMaster is the specialized cement formulation optimized for concrete block production. The enhanced workability reduces water demand while maintaining mold-filling characteristics, resulting in denser blocks with higher compressive strength and lower water absorption. The controlled setting time accommodates manual and machine block molding operations, and the improved cohesiveness reduces edge chipping during demolding. The consistent color ensures uniform block appearance for visible masonry works. For block manufacturers who want cement specifically engineered for optimal block density, strength, and production efficiency. Condition: Brand new, sealed Dangote factory bag.', 1, 1718400000, 1, 5000, '/assets/products/dangote-blocmaster.webp', 6000, 4.5, 0, 'Dangote', 0, 1, 'buildmart');

INSERT OR REPLACE INTO products (id, name, category, basePrice, price, wholesalePrice, stock, weightKg, image, description, active, createdAt, wholesale_available, wholesale_price, image_url, reseller_price, rating, featured, brand, is_bestseller, is_new, store_type)
VALUES ('lafarge-powermax-cement', 'Lafarge PowerMax Cement — 50kg Bag, High Early Strength (New)', 'cement-concrete', 8200, 8200, 6000, 10, 50.0, '/assets/products/lafarge-powermax-cement.webp', 'Lafarge PowerMax is the high-performance cement for demanding structural applications. The enhanced early strength development achieves 20 MPa at 2 days and 35 MPa at 7 days, enabling rapid formwork cycling and accelerated construction programs. The low heat of hydration formulation minimizes thermal gradients in thick sections, reducing crack risk in foundations and retaining walls. The improved durability characteristics enhance resistance to aggressive environments including sulfate-bearing soils and marine exposure. For commercial developers and infrastructure contractors who need maximum early strength and long-term durability for critical structural elements. Condition: Brand new, sealed Lafarge factory bag, QR-coded.', 1, 1718400000, 1, 6000, '/assets/products/lafarge-powermax-cement.webp', 7000, 4.5, 0, 'Lafarge', 0, 1, 'buildmart');

INSERT OR REPLACE INTO products (id, name, category, basePrice, price, wholesalePrice, stock, weightKg, image, description, active, createdAt, wholesale_available, wholesale_price, image_url, reseller_price, rating, featured, brand, is_bestseller, is_new, store_type)
VALUES ('dangote-plastermaster', 'Dangote PlasterMaster — 50kg Bag, Finishing Cement (New)', 'cement-concrete', 7000, 7000, 5000, 10, 50.0, '/assets/products/dangote-plastermaster.webp', 'Dangote PlasterMaster is the finishing-grade cement formulated specifically for plastering, rendering, and screeding applications. The ultra-fine grind produces exceptionally smooth finishes with minimal trowel work, and the enhanced workability extends open time for large-area plastering. The controlled setting time prevents premature stiffening in hot weather, and the bright white color provides an excellent base for paint application. The low shrinkage characteristics minimize plaster cracking and crazing. For plastering contractors and finishing teams who want a cement that delivers mirror-smooth walls with reduced labor and material waste. Condition: Brand new, sealed Dangote factory bag.', 1, 1718400000, 1, 5000, '/assets/products/dangote-plastermaster.webp', 6000, 4.5, 0, 'Dangote', 0, 1, 'buildmart');

INSERT OR REPLACE INTO products (id, name, category, basePrice, price, wholesalePrice, stock, weightKg, image, description, active, createdAt, wholesale_available, wholesale_price, image_url, reseller_price, rating, featured, brand, is_bestseller, is_new, store_type)
VALUES ('white-cement', 'White Cement — 50kg Bag, Decorative & Tile Works (New)', 'cement-concrete', 18500, 18500, 15000, 10, 50.0, '/assets/products/white-cement.webp', 'White Portland Cement is the premium binder for decorative concrete, terrazzo, tile grouting, and architectural finishes. The low iron content in the raw materials produces the characteristic brilliant white color, providing an ideal base for pigmented finishes and ensuring consistent color in decorative applications. The fine particle size enables smooth, refined surfaces in architectural precast and cast stone. When mixed with marble dust and pigments, it creates stunning terrazzo and mosaic finishes. For architects, interior designers, and finishing contractors who demand pristine white surfaces for luxury residential and commercial interiors. Condition: Brand new, sealed imported or locally manufactured bag.', 1, 1718400000, 1, 15000, '/assets/products/white-cement.webp', 16000, 4.5, 0, 'Generic', 0, 1, 'buildmart');

INSERT OR REPLACE INTO products (id, name, category, basePrice, price, wholesalePrice, stock, weightKg, image, description, active, createdAt, wholesale_available, wholesale_price, image_url, reseller_price, rating, featured, brand, is_bestseller, is_new, store_type)
VALUES ('ready-mix-concrete', 'Ready-Mix Concrete — Grade 25, Per Cubic Meter, Delivered (New)', 'cement-concrete', 65000, 65000, 53000, 10, 2400.0, '/assets/products/ready-mix-concrete.webp', 'Ready-Mix Concrete Grade 25 is the pre-mixed solution for consistent, quality-controlled concrete placement. Batched in certified plants with computerized proportioning, each cubic meter delivers 25 N/mm² characteristic compressive strength at 28 days with guaranteed mix design compliance. The controlled slump and workability ensure proper placement and compaction, and the delivery within 90 minutes of batching maintains freshness. Available with retarders for hot-weather pouring and accelerators for cold-weather applications. For contractors who want to eliminate on-site batching inconsistency and ensure structural compliance with minimal waste. Condition: Fresh batch, delivered by certified ready-mix supplier with test certificates.', 1, 1718400000, 1, 53000, '/assets/products/ready-mix-concrete.webp', 59000, 4.5, 1, 'Generic', 0, 1, 'buildmart');

INSERT OR REPLACE INTO products (id, name, category, basePrice, price, wholesalePrice, stock, weightKg, image, description, active, createdAt, wholesale_available, wholesale_price, image_url, reseller_price, rating, featured, brand, is_bestseller, is_new, store_type)
VALUES ('ready-mix-concrete-1', 'Ready-Mix Concrete — Grade 30, Per Cubic Meter, Delivered (New)', 'cement-concrete', 72000, 72000, 59000, 10, 2400.0, '/assets/products/ready-mix-concrete-1.webp', 'Ready-Mix Concrete Grade 30 delivers enhanced structural capacity for columns, beams, and suspended slabs. The optimized mix design with controlled water-cement ratio achieves 30 N/mm² characteristic strength with improved durability properties. The air-entrainment option enhances freeze-thaw resistance for exposed applications, and the plasticizers improve workability without increasing water content. Each delivery includes batch tickets with mix proportions, slump test results, and delivery time documentation. For structural engineers and contractors working on multi-story buildings and load-bearing elements requiring higher strength concrete. Condition: Fresh batch, delivered with batch tickets and quality documentation.', 1, 1718400000, 1, 59000, '/assets/products/ready-mix-concrete-1.webp', 65000, 4.5, 1, 'Generic', 0, 1, 'buildmart');

INSERT OR REPLACE INTO products (id, name, category, basePrice, price, wholesalePrice, stock, weightKg, image, description, active, createdAt, wholesale_available, wholesale_price, image_url, reseller_price, rating, featured, brand, is_bestseller, is_new, store_type)
VALUES ('ready-mix-concrete-2', 'Ready-Mix Concrete — Grade 35, Per Cubic Meter, Delivered (New)', 'cement-concrete', 82000, 82000, 67000, 10, 2400.0, '/assets/products/ready-mix-concrete-2.webp', 'Ready-Mix Concrete Grade 35 is the high-strength solution for critical structural elements including high-rise columns, bridge decks, and heavy industrial floors. The low water-cement ratio with superplasticizers achieves 35 N/mm² with excellent density and low permeability. The silica fume or fly ash additions enhance long-term strength gain and durability in aggressive environments. The controlled curing recommendations ensure achievement of specified strength at 28 days. For infrastructure projects, high-rise construction, and industrial applications where structural performance and durability are paramount. Condition: Fresh batch, delivered with comprehensive test documentation.', 1, 1718400000, 1, 67000, '/assets/products/ready-mix-concrete-2.webp', 74000, 4.5, 1, 'Generic', 0, 1, 'buildmart');

INSERT OR REPLACE INTO products (id, name, category, basePrice, price, wholesalePrice, stock, weightKg, image, description, active, createdAt, wholesale_available, wholesale_price, image_url, reseller_price, rating, featured, brand, is_bestseller, is_new, store_type)
VALUES ('sharp-sand', 'Sharp Sand — Tipper Load, 20 Tons, Screened & Washed (New)', 'cement-concrete', 95000, 95000, 77000, 10, 20000.0, '/assets/products/sharp-sand.webp', 'Sharp Sand is the coarse, angular aggregate essential for concrete production, block molding, and floor screeding. The screened and washed processing removes clay, silt, and organic matter that would weaken concrete bonds, ensuring consistent mix quality. The angular particle shape provides excellent mechanical interlock in concrete, enhancing compressive strength. Each 20-ton tipper load is sourced from approved quarries with consistent grading curves. For builders who want clean, graded sharp sand that delivers predictable concrete strength and workability without contamination-related failures. Condition: Fresh quarry delivery, screened and washed, free from organic contamination.', 1, 1718400000, 1, 77000, '/assets/products/sharp-sand.webp', 86000, 4.5, 1, 'Generic', 0, 1, 'buildmart');

INSERT OR REPLACE INTO products (id, name, category, basePrice, price, wholesalePrice, stock, weightKg, image, description, active, createdAt, wholesale_available, wholesale_price, image_url, reseller_price, rating, featured, brand, is_bestseller, is_new, store_type)
VALUES ('plaster-sand', 'Plaster Sand — Tipper Load, 20 Tons, Fine Grade (New)', 'cement-concrete', 85000, 85000, 69000, 10, 20000.0, '/assets/products/plaster-sand.webp', 'Plaster Sand is the fine, clean aggregate specifically graded for plastering, rendering, and mortar applications. The fine particle size with minimal clay content produces smooth, workable plaster that adheres well to block and concrete substrates. The consistent grading ensures uniform mix proportions, preventing plaster cracking and debonding. The low silt content maintains plaster strength and prevents surface dusting. Each 20-ton load is washed and screened to specification. For plastering contractors who need fine, clean sand that produces flawless wall and ceiling finishes. Condition: Fresh quarry delivery, washed and screened to fine grade.', 1, 1718400000, 1, 69000, '/assets/products/plaster-sand.webp', 77000, 4.5, 1, 'Generic', 0, 1, 'buildmart');

INSERT OR REPLACE INTO products (id, name, category, basePrice, price, wholesalePrice, stock, weightKg, image, description, active, createdAt, wholesale_available, wholesale_price, image_url, reseller_price, rating, featured, brand, is_bestseller, is_new, store_type)
VALUES ('granite-aggregate', 'Granite Aggregate — 3/4 Inch, Tipper Load, 20 Tons, Crushed (New)', 'cement-concrete', 125000, 125000, 102000, 10, 20000.0, '/assets/products/granite-aggregate.webp', '3/4 Inch Granite Aggregate is the primary coarse aggregate for structural concrete, providing the bulk and strength that defines concrete performance. The crushed granite particles with rough surfaces create strong mechanical bonds with cement paste, while the controlled grading ensures optimal packing density. The low water absorption and high crushing value meet specifications for reinforced concrete in buildings and infrastructure. Each 20-ton tipper load is sourced from hard-rock quarries with consistent geological properties. For structural concrete contractors who demand aggregate that meets BS EN 12620 standards for strength and durability. Condition: Fresh quarry delivery, crushed and screened to 3/4 inch, free from clay lumps.', 1, 1718400000, 1, 102000, '/assets/products/granite-aggregate.webp', 113000, 4.5, 1, 'Generic', 0, 1, 'buildmart');

INSERT OR REPLACE INTO products (id, name, category, basePrice, price, wholesalePrice, stock, weightKg, image, description, active, createdAt, wholesale_available, wholesale_price, image_url, reseller_price, rating, featured, brand, is_bestseller, is_new, store_type)
VALUES ('granite-aggregate-1', 'Granite Aggregate — 1/2 Inch, Tipper Load, 20 Tons, Crushed (New)', 'cement-concrete', 120000, 120000, 98000, 10, 20000.0, '/assets/products/granite-aggregate-1.webp', '1/2 Inch Granite Aggregate is the smaller coarse aggregate used in high-strength concrete, floor screeds, and specialized applications requiring denser packing. The smaller maximum size reduces void content and improves concrete density, enhancing compressive strength and impermeability. The controlled flakiness index ensures predominantly cubical particles that pack efficiently. Suitable for pumped concrete, thin structural sections, and decorative exposed aggregate finishes. Each 20-ton load is quality-controlled for grading and cleanliness. For contractors working on high-strength concrete, thin slabs, and architectural concrete finishes. Condition: Fresh quarry delivery, crushed and screened to 1/2 inch.', 1, 1718400000, 1, 98000, '/assets/products/granite-aggregate-1.webp', 109000, 4.5, 1, 'Generic', 0, 1, 'buildmart');

INSERT OR REPLACE INTO products (id, name, category, basePrice, price, wholesalePrice, stock, weightKg, image, description, active, createdAt, wholesale_available, wholesale_price, image_url, reseller_price, rating, featured, brand, is_bestseller, is_new, store_type)
VALUES ('granite-duststone-dust', 'Granite Dust/Stone Dust — Tipper Load, 20 Tons (New)', 'cement-concrete', 75000, 75000, 61000, 10, 20000.0, '/assets/products/granite-duststone-dust.webp', 'Granite Dust is the fine byproduct of granite crushing, valued as a partial sand replacement in concrete and as a bedding material for paving. When used as a sand substitute up to 30%, it improves concrete density and reduces voids, enhancing strength and impermeability. As a paver bedding material, it provides excellent compaction and drainage. The angular particles interlock effectively, preventing settling and maintaining level surfaces. Each 20-ton load is consistent in gradation and free from oversized particles. For cost-conscious builders who want to improve concrete properties while reducing sand costs, and for paving contractors needing stable bedding material. Condition: Fresh quarry delivery, consistent gradation.', 1, 1718400000, 1, 61000, '/assets/products/granite-duststone-dust.webp', 68000, 4.5, 1, 'Generic', 0, 1, 'buildmart');

INSERT OR REPLACE INTO products (id, name, category, basePrice, price, wholesalePrice, stock, weightKg, image, description, active, createdAt, wholesale_available, wholesale_price, image_url, reseller_price, rating, featured, brand, is_bestseller, is_new, store_type)
VALUES ('laterite', 'Laterite — Tipper Load, 20 Tons, Red Earth Filling (New)', 'cement-concrete', 55000, 55000, 45000, 10, 20000.0, '/assets/products/laterite.webp', 'Laterite is the naturally occurring red earth material used for site filling, road base construction, and brick manufacturing. The iron oxide content provides natural cementation when compacted, creating stable fill layers for foundation platforms and road sub-bases. The granular structure with some clay content compacts to high densities with proper moisture conditioning. Suitable for site leveling, backfilling, and as a base course material for access roads. Each 20-ton load is sourced from approved borrow pits with consistent properties. For site developers and earthworks contractors who need affordable, locally available filling material with natural binding properties. Condition: Fresh borrow pit delivery, free from organic matter and oversized stones.', 1, 1718400000, 1, 45000, '/assets/products/laterite.webp', 50000, 4.5, 1, 'Generic', 0, 1, 'buildmart');

INSERT OR REPLACE INTO products (id, name, category, basePrice, price, wholesalePrice, stock, weightKg, image, description, active, createdAt, wholesale_available, wholesale_price, image_url, reseller_price, rating, featured, brand, is_bestseller, is_new, store_type)
VALUES ('tmt-iron-rod', 'TMT Iron Rod — 12mm, Full Length (12m), Per Piece, Y12 (New)', 'steel-reinforcement', 8500, 8500, 6000, 10, 86.39999999999999, '/assets/products/tmt-iron-rod.webp', 'TMT (Thermo-Mechanically Treated) Iron Rod 12mm is the standard reinforcement bar for beams, columns, and slabs in residential and commercial construction. The thermo-mechanical treatment creates a hard outer martensitic layer with a soft ferrite-pearlite core, providing high yield strength with excellent ductility and bendability. The ribbed surface pattern ensures superior bond with concrete, preventing slippage under load. Each 12-meter length meets Nigerian Standard NIS 117:2010 with guaranteed yield strength of 500 MPa. For structural engineers and contractors who need reliable reinforcement that meets building code requirements for seismic and structural applications. Condition: Brand new, mill-certified, batch-tested with mill test certificates.', 1, 1718400000, 1, 6000, '/assets/products/tmt-iron-rod.webp', 7000, 4.5, 0, 'TMT', 0, 1, 'buildmart');

INSERT OR REPLACE INTO products (id, name, category, basePrice, price, wholesalePrice, stock, weightKg, image, description, active, createdAt, wholesale_available, wholesale_price, image_url, reseller_price, rating, featured, brand, is_bestseller, is_new, store_type)
VALUES ('tmt-iron-rod-1', 'TMT Iron Rod — 16mm, Full Length (12m), Per Piece, Y16 (New)', 'steel-reinforcement', 15200, 15200, 12000, 10, 115.19999999999999, '/assets/products/tmt-iron-rod-1.webp', 'TMT Iron Rod 16mm is the primary reinforcement for columns, beams, and heavy slabs in multi-story construction. The 16mm diameter provides the cross-sectional area needed for high-load structural elements, and the TMT process ensures the strength-ductility balance required by modern building codes. The consistent rib pattern and dimensional tolerances meet international standards, and the mill test certificates verify chemical composition and mechanical properties. Each bar is clearly marked with grade, diameter, and manufacturer identification. For structural contractors working on buildings exceeding two stories who need certified reinforcement for code-compliant construction. Condition: Brand new, mill-certified with test certificates, clearly marked.', 1, 1718400000, 1, 12000, '/assets/products/tmt-iron-rod-1.webp', 13000, 4.5, 0, 'TMT', 0, 1, 'buildmart');

INSERT OR REPLACE INTO products (id, name, category, basePrice, price, wholesalePrice, stock, weightKg, image, description, active, createdAt, wholesale_available, wholesale_price, image_url, reseller_price, rating, featured, brand, is_bestseller, is_new, store_type)
VALUES ('tmt-iron-rod-2', 'TMT Iron Rod — 10mm, Full Length (12m), Per Piece, Y10 (New)', 'steel-reinforcement', 5800, 5800, 4000, 10, 72.0, '/assets/products/tmt-iron-rod-2.webp', 'TMT Iron Rod 10mm is the versatile reinforcement bar used for stirrups, distribution bars, light slabs, and secondary reinforcement. The smaller diameter enables tight bending radii for stirrup formation, and the TMT properties ensure the bends do not crack or fracture. The consistent quality enables reliable calculation of reinforcement ratios, and the ribbed surface provides adequate bond for effective stress transfer. Suitable for ring beams, lintels, staircases, and as temperature reinforcement in slabs. For contractors and detailers who need reliable small-diameter reinforcement for ties, stirrups, and light structural elements. Condition: Brand new, mill-certified with test certificates.', 1, 1718400000, 1, 4000, '/assets/products/tmt-iron-rod-2.webp', 5000, 4.5, 0, 'TMT', 0, 1, 'buildmart');

INSERT OR REPLACE INTO products (id, name, category, basePrice, price, wholesalePrice, stock, weightKg, image, description, active, createdAt, wholesale_available, wholesale_price, image_url, reseller_price, rating, featured, brand, is_bestseller, is_new, store_type)
VALUES ('tmt-iron-rod-3', 'TMT Iron Rod — 8mm, Full Length (12m), Per Piece, Y8 (New)', 'steel-reinforcement', 3800, 3800, 3000, 10, 57.599999999999994, '/assets/products/tmt-iron-rod-3.webp', 'TMT Iron Rod 8mm is the light reinforcement used for distribution bars in slabs, wall ties, and light structural ties. The small diameter enables easy manual bending on site, and the TMT ductility ensures bends withstand handling without fracture. The ribbed surface provides sufficient bond for its typical applications, and the consistent diameter ensures accurate spacing in slab reinforcement layouts. Suitable for single-story residential slabs, block wall reinforcement, and non-structural applications. For small-scale builders and homeowners who need affordable reinforcement for light structural and distribution applications. Condition: Brand new, mill-certified.', 1, 1718400000, 1, 3000, '/assets/products/tmt-iron-rod-3.webp', 3000, 4.5, 0, 'TMT', 0, 1, 'buildmart');

INSERT OR REPLACE INTO products (id, name, category, basePrice, price, wholesalePrice, stock, weightKg, image, description, active, createdAt, wholesale_available, wholesale_price, image_url, reseller_price, rating, featured, brand, is_bestseller, is_new, store_type)
VALUES ('tmt-iron-rod-4', 'TMT Iron Rod — 20mm, Full Length (12m), Per Piece, Y20 (New)', 'steel-reinforcement', 23500, 23500, 19000, 10, 144.0, '/assets/products/tmt-iron-rod-4.webp', 'TMT Iron Rod 20mm is the heavy reinforcement for primary structural elements in high-rise buildings, bridges, and heavy industrial foundations. The large cross-sectional area provides the tensile capacity needed for columns in buildings exceeding five stories and for heavy foundation mats. The TMT process ensures that despite the large diameter, the core maintains sufficient ductility for seismic performance. The mill test certificates verify yield strength, tensile strength, and elongation percentages. For major construction contractors and infrastructure developers who need certified heavy reinforcement for critical structural elements. Condition: Brand new, mill-certified with full test certificates.', 1, 1718400000, 1, 19000, '/assets/products/tmt-iron-rod-4.webp', 21000, 4.5, 0, 'TMT', 0, 1, 'buildmart');

INSERT OR REPLACE INTO products (id, name, category, basePrice, price, wholesalePrice, stock, weightKg, image, description, active, createdAt, wholesale_available, wholesale_price, image_url, reseller_price, rating, featured, brand, is_bestseller, is_new, store_type)
VALUES ('tmt-iron-rod-5', 'TMT Iron Rod — 25mm, Full Length (12m), Per Piece, Y25 (New)', 'steel-reinforcement', 36500, 36500, 29000, 10, 180.0, '/assets/products/tmt-iron-rod-5.webp', 'TMT Iron Rod 25mm is the extra-heavy reinforcement for mega-structural elements including bridge piers, high-rise core walls, and heavy industrial foundations. The substantial cross-sectional area reduces the number of bars needed in congested reinforcement cages, improving concrete placement quality. The controlled cooling during TMT processing ensures through-thickness property uniformity even at this large diameter. Each bar is individually marked and traceable to mill test certificates. For infrastructure contractors and heavy engineering projects where maximum reinforcement capacity and traceability are required. Condition: Brand new, mill-certified with full traceability documentation.', 1, 1718400000, 1, 29000, '/assets/products/tmt-iron-rod-5.webp', 33000, 4.5, 0, 'TMT', 0, 1, 'buildmart');

INSERT OR REPLACE INTO products (id, name, category, basePrice, price, wholesalePrice, stock, weightKg, image, description, active, createdAt, wholesale_available, wholesale_price, image_url, reseller_price, rating, featured, brand, is_bestseller, is_new, store_type)
VALUES ('tmt-iron-rod-6', 'TMT Iron Rod — 32mm, Full Length (12m), Per Piece, Y32 (New)', 'steel-reinforcement', 58000, 58000, 47000, 10, 230.39999999999998, '/assets/products/tmt-iron-rod-6.webp', 'TMT Iron Rod 32mm is the maximum-diameter reinforcement for massive structural elements in dams, deep foundations, and heavy industrial structures. The enormous tensile capacity per bar reduces congestion in heavily reinforced sections, facilitating concrete vibration and ensuring proper compaction around reinforcement. The specialized TMT processing for large diameters maintains the required ductility for seismic and impact resistance. Each bar is subject to rigorous testing including tensile tests, bend tests, and chemical analysis. For heavy civil engineering contractors working on infrastructure, industrial, and monumental structures requiring maximum reinforcement capacity. Condition: Brand new, mill-certified with comprehensive test documentation.', 1, 1718400000, 1, 47000, '/assets/products/tmt-iron-rod-6.webp', 52000, 4.5, 1, 'TMT', 0, 1, 'buildmart');

INSERT OR REPLACE INTO products (id, name, category, basePrice, price, wholesalePrice, stock, weightKg, image, description, active, createdAt, wholesale_available, wholesale_price, image_url, reseller_price, rating, featured, brand, is_bestseller, is_new, store_type)
VALUES ('binding-wire', 'Binding Wire — 18 Gauge, 20kg Roll, Black Annealed (New)', 'steel-reinforcement', 18500, 18500, 15000, 10, 20.0, '/assets/products/binding-wire.webp', 'Binding Wire is the black annealed steel wire used to secure reinforcement bars during concrete formwork preparation. The 18-gauge diameter provides the right balance of strength and flexibility for hand-tying reinforcement intersections, and the annealing process softens the wire for easy twisting without breaking. The black oxide coating provides mild corrosion resistance during the construction period. Each 20kg roll contains approximately 800-900 meters of wire, sufficient for tying several tons of reinforcement. For reinforcement fixers and contractors who need reliable binding wire that ties securely without snapping during installation. Condition: Brand new, annealed steel wire on standard roll.', 1, 1718400000, 1, 15000, '/assets/products/binding-wire.webp', 16000, 4.5, 0, 'Generic', 0, 1, 'buildmart');

INSERT OR REPLACE INTO products (id, name, category, basePrice, price, wholesalePrice, stock, weightKg, image, description, active, createdAt, wholesale_available, wholesale_price, image_url, reseller_price, rating, featured, brand, is_bestseller, is_new, store_type)
VALUES ('brc-mesh', 'BRC Mesh — A142, 2.4m x 4.8m Sheet, Galvanized (New)', 'steel-reinforcement', 32000, 32000, 26000, 10, 50.0, '/assets/products/brc-mesh.webp', 'BRC Mesh A142 is the welded steel reinforcement mesh for ground floor slabs, pavements, and light structural applications. The A142 designation indicates 200mm x 200mm grid spacing with 6mm wires, providing a cross-sectional area of 142 mm² per meter width. The welded intersections ensure rigid positioning during concrete placement, and the galvanized coating provides corrosion protection for ground-bearing applications. Each 2.4m x 4.8m sheet covers 11.52 square meters, reducing installation time compared to individual bar placement. For ground floor slab contractors and paving specialists who want rapid, consistent reinforcement installation with proven performance. Condition: Brand new, galvanized welded mesh, flat sheet delivery.', 1, 1718400000, 1, 26000, '/assets/products/brc-mesh.webp', 29000, 4.5, 0, 'BRC', 0, 1, 'buildmart');

INSERT OR REPLACE INTO products (id, name, category, basePrice, price, wholesalePrice, stock, weightKg, image, description, active, createdAt, wholesale_available, wholesale_price, image_url, reseller_price, rating, featured, brand, is_bestseller, is_new, store_type)
VALUES ('brc-mesh-1', 'BRC Mesh — A193, 2.4m x 4.8m Sheet, Galvanized (New)', 'steel-reinforcement', 42000, 42000, 34000, 10, 50.0, '/assets/products/brc-mesh-1.webp', 'BRC Mesh A193 is the heavier welded mesh for industrial floors, heavy pavements, and structural slabs requiring enhanced reinforcement. The 200mm x 200mm grid with 7mm wires provides 193 mm² per meter width, offering greater crack control and load distribution. The welded grid maintains precise spacing during concrete vibration, and the galvanized coating extends service life in ground-contact applications. Each sheet covers 11.52 square meters with consistent bar spacing that eliminates manual measurement errors. For industrial flooring contractors and structural slab specialists who need enhanced reinforcement with rapid installation. Condition: Brand new, galvanized welded mesh, flat sheet delivery.', 1, 1718400000, 1, 34000, '/assets/products/brc-mesh-1.webp', 38000, 4.5, 0, 'BRC', 0, 1, 'buildmart');

INSERT OR REPLACE INTO products (id, name, category, basePrice, price, wholesalePrice, stock, weightKg, image, description, active, createdAt, wholesale_available, wholesale_price, image_url, reseller_price, rating, featured, brand, is_bestseller, is_new, store_type)
VALUES ('brc-mesh-2', 'BRC Mesh — A252, 2.4m x 4.8m Sheet, Galvanized (New)', 'steel-reinforcement', 55000, 55000, 45000, 10, 50.0, '/assets/products/brc-mesh-2.webp', 'BRC Mesh A252 is the heavy-duty welded mesh for warehouse floors, heavy-duty pavements, and suspended slabs with significant loads. The 200mm x 200mm grid with 8mm wires provides 252 mm² per meter width, delivering substantial reinforcement capacity for high-load applications. The rigid welded construction maintains bar positions during concrete placement and vibration, ensuring design reinforcement ratios are achieved. The galvanized finish provides protection against moisture and chemical exposure in industrial environments. For industrial contractors and warehouse developers who need maximum mesh reinforcement for heavy-duty concrete floors. Condition: Brand new, galvanized welded mesh, flat sheet delivery.', 1, 1718400000, 1, 45000, '/assets/products/brc-mesh-2.webp', 50000, 4.5, 1, 'BRC', 0, 1, 'buildmart');

INSERT OR REPLACE INTO products (id, name, category, basePrice, price, wholesalePrice, stock, weightKg, image, description, active, createdAt, wholesale_available, wholesale_price, image_url, reseller_price, rating, featured, brand, is_bestseller, is_new, store_type)
VALUES ('brc-mesh-3', 'BRC Mesh — A393, 2.4m x 4.8m Sheet, Galvanized (New)', 'steel-reinforcement', 78000, 78000, 63000, 10, 50.0, '/assets/products/brc-mesh-3.webp', 'BRC Mesh A393 is the extra-heavy welded mesh for bridge decks, heavy industrial slabs, and structural elements requiring maximum distributed reinforcement. The 200mm x 200mm grid with 10mm wires provides 393 mm² per meter width, approaching the capacity of individual bar reinforcement with the speed of mesh installation. The high-strength welded joints withstand construction traffic and concrete placement forces without displacement. For infrastructure contractors and heavy industrial developers who need maximum mesh reinforcement capacity with the installation efficiency of prefabricated sheets. Condition: Brand new, galvanized welded mesh, flat sheet delivery.', 1, 1718400000, 1, 63000, '/assets/products/brc-mesh-3.webp', 70000, 4.5, 1, 'BRC', 0, 1, 'buildmart');

